# Search for the exact point where host tests start in the grader tail
results = await CONTEXT.search("\\[host\\]")
if results["items"]:
    for item in results["items"]:
        offset = item["offset"]
        print(f"offset={offset}")
        r = await CONTEXT.read(offset, 2000)
        print(r)

